def arrival_date_offset(depart_hh, depart_mm, duration_minutes):
    total = depart_hh * 60 + depart_mm + duration_minutes
    return total // 1440

def double_shift_day_delta(hh, mm, offset_minutes):
    total = hh * 60 + mm + offset_minutes
    shift = total // 1440
    if shift > 0:
        return "next"
    if shift < 0:
        return "previous"
    return "same"

def count_weekends_in_day_range(start_day_num, end_day_num):
    n = end_day_num - start_day_num + 1
    full_weeks, rem = divmod(n, 7)
    count = full_weeks * 2
    for i in range(rem):
        wd = (start_day_num + i) % 7
        if wd in (5, 6):
            count += 1
    return count

def count_weekdays_in_day_range(start_day_num, end_day_num):
    n = end_day_num - start_day_num + 1
    full_weeks, rem = divmod(n, 7)
    count = full_weeks * 5
    for i in range(rem):
        wd = (start_day_num + i) % 7
        if wd < 5:
            count += 1
    return count

def count_specific_weekday_in_range(start_day_num, end_day_num, weekday):
    n = end_day_num - start_day_num + 1
    full_weeks, rem = divmod(n, 7)
    count = full_weeks
    for i in range(rem):
        wd = (start_day_num + i) % 7
        if wd == weekday:
            count += 1
    return count

def first_weekend_day_on_or_after(day_num):
    wd = day_num % 7
    if wd in (5, 6):
        return day_num
    return day_num + (5 - wd) % 7

def first_weekday_on_or_after_daynum(day_num):
    wd = day_num % 7
    if wd < 5:
        return day_num
    return day_num + (7 - wd) % 7

def count_full_weekends_in_range(start_day_num, end_day_num):
    wd = start_day_num % 7
    s0 = start_day_num + (5 - wd) % 7
    if s0 + 1 > end_day_num:
        return 0
    return (end_day_num - 1 - s0) // 7 + 1

def nth_weekend_day_from(day_num, n):
    wd = day_num % 7
    if wd == 6:
        if n == 1:
            return day_num
        n -= 1
        s0 = day_num + 6
    else:
        s0 = day_num + (5 - wd) % 7
    k = (n - 1) // 2
    offset = (n - 1) % 2
    return s0 + 7 * k + offset

def previous_business_day(day_num, weekend_days):
    weekend_set = set(weekend_days)
    current = day_num - 1
    while current % 7 in weekend_set:
        current -= 1
    return current

def nearest_business_day(day_num, weekend_days):
    weekend_set = set(weekend_days)
    current = day_num
    while current % 7 in weekend_set:
        current += 1
    return current

def count_non_business_days(start_day_num, end_day_num, weekend_days):
    weekend_set = set(weekend_days)
    n = end_day_num - start_day_num + 1
    full_weeks, rem = divmod(n, 7)
    count = full_weeks * len(weekend_set)
    for i in range(rem):
        wd = (start_day_num + i) % 7
        if wd in weekend_set:
            count += 1
    return count

def last_business_day_of_week(week_start_day_num, weekend_days):
    weekend_set = set(weekend_days)
    for day in range(week_start_day_num + 6, week_start_day_num - 1, -1):
        if day % 7 not in weekend_set:
            return day
